<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response};use App\Repositories\{AcademicRepository,OnlineTestRepository,PakistanErpRepository,SettingsRepository};use App\Support\{Flash,SecureAttachment};
final class OnlineTestsController extends AdminPageController{
private function i():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}private function r():OnlineTestRepository{return new OnlineTestRepository($this->app->database());}
private function employee():?int{$v=$this->app->database()->query('SELECT employee_id FROM employee_accounts WHERE user_id=:u',['u'=>(int)user()['id']])->fetchColumn();return$v?(int)$v:null;}
private function owns(int$test):bool{return can('*')||(bool)$this->app->database()->query('SELECT 1 FROM online_tests WHERE id=:id AND created_by=:u',['id'=>$test,'u'=>(int)user()['id']])->fetchColumn();}
private function ownsAttempt(int$attemptId):bool{return can('*')||(bool)$this->app->database()->query('SELECT 1 FROM online_test_attempts a JOIN online_tests t ON t.id=a.test_id WHERE a.id=:id AND t.created_by=:u',['id'=>$attemptId,'u'=>(int)user()['id']])->fetchColumn();}
public function index(Request$r):Response{$i=$this->i();$classes=(new AcademicRepository($this->app->database()))->withSubjects($i);$tests=$this->r()->all($i);if(!can('*')&&($e=$this->employee())){$assign=(new PakistanErpRepository($this->app->database()))->assignments($i);$allowed=[];foreach($assign as$a)if((int)$a['employee_id']===$e)$allowed[(int)$a['class_id']]=true;$classes=array_values(array_filter($classes,fn($c)=>isset($allowed[(int)$c['id']])));$tests=array_values(array_filter($tests,fn($t)=>(int)$t['created_by']===(int)user()['id']));}return$this->view('online-tests/index',['pageTitle'=>'Online Tests','activeMenu'=>'online-tests','activeSubmenu'=>'online-tests','tests'=>$tests,'classes'=>$classes,'uploadSettings'=>$this->r()->settings($i),'styles'=>['css/online-tests.css?v=2','css/upload-only-tests.css?v=2','css/online-test-mobile.css?v=1','css/submission-actions.css?v=1','css/upload-settings.css?v=1'],'scripts'=>['js/online-test-builder.js?v=3']]);}
public function store(Request$r):Response{try{$i=$this->i();if(!can('*')){$e=$this->employee();if(!$e||!(new PakistanErpRepository($this->app->database()))->teacherCan($e,$i,(int)$r->input('class_id'),(int)$r->input('subject_id')))throw new \DomainException('You are not assigned to that class and subject.');}$questions=[];$files=$r->file('question_attachment');foreach((array)$r->input('question_text',[])as$k=>$text)$questions[]=['text'=>$text,'type'=>$r->input('question_type',[])[$k]??'written','marks'=>$r->input('question_marks',[])[$k]??0,'options'=>$r->input('question_options',[])[$k]??[],'correct'=>$r->input('correct_option',[])[$k]??-1,'attachment'=>SecureAttachment::store(SecureAttachment::nested($files,$k),'test-questions')];$this->r()->create($i,$r->all(),$questions,(int)user()['id']);Flash::add('success','Online test created as a draft.');}catch(\DomainException$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/online-tests'));}
/** Edit screen for a test (details, time, page limit and questions). */
public function edit(Request$r):Response{
    $id=(int)$r->route('id');if(!$this->owns($id))return Response::html('Forbidden',403);
    $test=$this->r()->forEdit($this->i(),$id);if(!$test)return Response::html('Test not found',404);
    $classes=(new AcademicRepository($this->app->database()))->withSubjects($this->i());
    if(!can('*')&&($e=$this->employee())){$allowed=[];foreach((new PakistanErpRepository($this->app->database()))->assignments($this->i())as$a)if((int)$a['employee_id']===$e)$allowed[(int)$a['class_id']]=true;$classes=array_values(array_filter($classes,fn($c)=>isset($allowed[(int)$c['id']])||(int)$c['id']===(int)$test['class_id']));}
    return$this->view('online-tests/edit',['pageTitle'=>'Edit Test','activeMenu'=>'online-tests','activeSubmenu'=>'online-tests','test'=>$test,'classes'=>$classes,'uploadSettings'=>$this->r()->settings($this->i()),'styles'=>['css/online-tests.css?v=2','css/upload-only-tests.css?v=2','css/online-test-mobile.css?v=1','css/upload-settings.css?v=1','css/test-edit.css?v=1'],'scripts'=>['js/online-test-edit.js?v=1']]);
}
public function update(Request$r):Response{
    $id=(int)$r->route('id');if(!$this->owns($id))return Response::html('Forbidden',403);
    $i=$this->i();$stored=[];
    try{
        if(!can('*')){$e=$this->employee();if(!$e||!(new PakistanErpRepository($this->app->database()))->teacherCan($e,$i,(int)$r->input('class_id'),(int)$r->input('subject_id')))throw new \DomainException('You are not assigned to that class and subject.');}
        $files=$r->file('question_file');$questions=[];
        foreach((array)$r->input('question',[])as$qid=>$q){$q=(array)$q;$path=SecureAttachment::store(SecureAttachment::nested($files,$qid),'test-questions');if($path)$stored[]=$path;$questions[(int)$qid]=['text'=>$q['text']??null,'marks'=>$q['marks']??null,'options'=>(array)($q['options']??[]),'correct'=>$q['correct']??null,'attachment'=>$path,'remove_attachment'=>!empty($q['remove_attachment'])];}
        $added=[];$newFiles=$r->file('new_question_attachment');
        foreach((array)$r->input('new_question_text',[])as$k=>$text){$path=SecureAttachment::store(SecureAttachment::nested($newFiles,$k),'test-questions');if($path)$stored[]=$path;if(trim((string)$text)===''&&!$path&&(float)($r->input('new_question_marks',[])[$k]??0)<=0)continue;$added[]=['text'=>$text,'type'=>$r->input('new_question_type',[])[$k]??'written','marks'=>$r->input('new_question_marks',[])[$k]??0,'options'=>$r->input('new_question_options',[])[$k]??[],'correct'=>$r->input('new_correct_option',[])[$k]??-1,'attachment'=>$path];}
        $rescored=$this->r()->update($i,$id,$r->all(),$questions,$added,array_map('intval',(array)$r->input('remove_question',[])));
        Flash::add('success','Test updated.'.($rescored?" {$rescored} marked paper".($rescored===1?' was':'s were').' re-scored with the new marks / answer key.':''));
        return Response::redirect(url('/admin/online-tests/'.$id.'/edit'));
    }catch(\DomainException|\RuntimeException$e){
        foreach($stored as$p)@unlink(BASE_PATH.'/'.$p);
        Flash::add('error',$e instanceof \DomainException?$e->getMessage():'A file could not be saved. Please try again.');
        return Response::redirect(url('/admin/online-tests/'.$id.'/edit'));
    }
}
/** Extra time for the whole class (adds to the test's time allowance). */
public function extend(Request$r):Response{
    $id=(int)$r->route('id');if(!$this->owns($id))return Response::html('Forbidden',403);
    try{[$duration,$closes,$writing]=$this->r()->extendTest($this->i(),$id,(int)$r->input('minutes'),(bool)$r->input('move_closing'));Flash::add('success','Everyone now has '.$duration.' minutes for this test'.($writing?" ({$writing} student".($writing===1?' is':'s are').' writing it now)':'').'.'.($closes&&$r->input('move_closing')?' It now closes at '.date('d M, h:i A',strtotime($closes)).'.':''));}
    catch(\DomainException$e){Flash::add('error',$e->getMessage());}
    return Response::redirect(url('/admin/online-tests/'.$id.'/submissions'));
}
/** Extra time for one student's attempt. */
public function extendAttempt(Request$r):Response{
    $attemptId=(int)$r->route('id');if(!$this->ownsAttempt($attemptId))return Response::html('Forbidden',403);
    $testId=(int)$this->app->database()->query('SELECT test_id FROM online_test_attempts WHERE id=:id',['id'=>$attemptId])->fetchColumn();
    try{$a=$this->r()->extendAttempt($this->i(),$attemptId,(int)$r->input('minutes'));Flash::add('success',$a['student_name'].' now has '.(int)$a['extra_minutes'].' extra minute'.((int)$a['extra_minutes']===1?'':'s').' ('.((int)$a['duration_minutes']+(int)$a['extra_minutes']).' in total).');}
    catch(\DomainException$e){Flash::add('error',$e->getMessage());}
    return Response::redirect(url('/admin/online-tests/'.$testId.'/submissions'));
}
/** Institute-wide student upload rules: default page limit and how long answer images are kept. */
public function settings(Request$r):Response{if(!can('*'))return Response::html('Forbidden',403);try{$this->r()->saveSettings($this->i(),(int)$r->input('max_pages'),(int)$r->input('retention_days'));$days=(int)$r->input('retention_days');Flash::add('success','Upload settings saved. '.($days>0?"Marked answer images will be kept for {$days} day".($days===1?'':'s').'.':'Answer images will be kept forever.'));}catch(\DomainException$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/online-tests#uploadSettings'));}
/** One test's page limit. */
public function pages(Request$r):Response{$id=(int)$r->route('id');if(!$this->owns($id))return Response::html('Forbidden',403);$n=(int)$r->input('max_pages');if($n<1||$n>OnlineTestRepository::HARD_MAX_PAGES){Flash::add('error','Pages must be between 1 and '.OnlineTestRepository::HARD_MAX_PAGES.'.');}else{$this->r()->setMaxPages($this->i(),$id,$n);Flash::add('success',"Students can now upload up to {$n} page".($n===1?'':'s').' for this test.');}return Response::redirect(url('/admin/online-tests#savedTests'));}
public function status(Request$r):Response{$id=(int)$r->route('id');if(!$this->owns($id))return Response::html('Forbidden',403);try{$this->r()->setStatus($this->i(),$id,(string)$r->input('status'));Flash::add('success','Test status updated.');}catch(\DomainException$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/online-tests'));}
public function delete(Request$r):Response{$id=(int)$r->route('id');if(!$this->owns($id))return Response::html('Forbidden',403);try{if(!$this->r()->delete($this->i(),$id))return Response::html('Test not found',404);Flash::add('success','Draft test deleted.');}catch(\DomainException$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/online-tests'));}
public function submissions(Request$r):Response{$id=(int)$r->route('id');if(!$this->owns($id))return Response::html('Forbidden',403);$test=$this->r()->find($this->i(),$id);if(!$test)return Response::html('Test not found',404);return$this->view('online-tests/submissions',['pageTitle'=>'Test Submissions','activeMenu'=>'online-tests','test'=>$test,'testId'=>$id,'submissions'=>$this->r()->submissions($this->i(),$id),'styles'=>['css/online-test-mobile.css?v=1','css/upload-settings.css?v=1']]);}
public function review(Request$r):Response{$a=$this->r()->attempt($this->i(),(int)$r->route('id'));if(!$a||!in_array($a['status'],['submitted','marked'],true)||!$this->ownsAttempt((int)$r->route('id')))return Response::html('Submitted attempt not found',404);return$this->view('online-tests/review',['pageTitle'=>'Mark Test','activeMenu'=>'online-tests','attempt'=>$a,'styles'=>['css/online-tests.css?v=2','css/online-test-mobile.css?v=1','css/test-uploads.css?v=1','css/upload-settings.css?v=1'],'scripts'=>['js/test-gallery.js?v=1']]);}
public function mark(Request$r):Response{$id=(int)$r->route('id');$a=$this->r()->attempt($this->i(),$id);if(!$a||!in_array($a['status'],['submitted','marked'],true)||!$this->ownsAttempt($id))return Response::html('Forbidden',403);try{$markedFiles=[];$files=$r->file('marked_paper');foreach(($files['name']??[])as$k=>$name)if($name!=='')$markedFiles[]=SecureAttachment::store(SecureAttachment::nested($files,$k),'test-marked');$this->r()->mark($this->i(),$id,(array)$r->input('score',[]),(array)$r->input('feedback',[]),(int)user()['id'],$markedFiles,$r->has('teacher_comment')?(string)$r->input('teacher_comment'):null);if($r->input('publish')){$repo=$this->r();$repo->publishResults($this->i(),(int)$a['test_id'],(string)$r->input('visible_to','both'),(int)user()['id']);$sms=$this->resultSms($repo->justPublished);Flash::add(str_contains($sms,'NOT sent')?'warning':'success','Marks saved and the result was published to the student.'.$sms);}else{Flash::add('success','Marks saved to the student progress record. Publish the result from the submissions list when ready.');}}catch(\DomainException$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/online-tests/submissions/'.$id));
}
/** Result SMS home for attempts that were just released (SMS Center → Automations → Result Published). */
private function resultSms(array$attemptIds):string{if(!$attemptIds)return'';$queued=(new \App\Services\Sms\SmsAutomation($this->app->database()))->onlineResultsPublished($this->i(),$attemptIds);$skipped=\App\Services\Sms\SmsAutomation::$lastSkipped;return($queued?' '.$queued.' result SMS queued for the SMS gateway.':'').($skipped?' Result SMS NOT sent for '.count($skipped).' student(s) — '.implode('; ',array_slice($skipped,0,3)).'.':'');}
public function publish(Request$r):Response{$id=(int)$r->route('id');if(!$this->owns($id))return Response::html('Forbidden',403);try{$visible=(string)$r->input('visible_to','both');$repo=$this->r();$count=$repo->publishResults($this->i(),$id,$visible,(int)user()['id']);$label=['student'=>'the students','parent'=>'parents only','both'=>'students and parents'][$visible]??'students and parents';$sms=$this->resultSms($repo->justPublished);Flash::add(str_contains($sms,'NOT sent')?'warning':'success',($count>0?"{$count} result(s) published to {$label}.":'There are no marked results waiting to be published.').$sms);}catch(\DomainException$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/online-tests/'.$id.'/submissions'));}
public function withdraw(Request$r):Response{$attemptId=(int)$r->route('id');if(!$this->ownsAttempt($attemptId))return Response::html('Forbidden',403);$a=$this->r()->attempt($this->i(),$attemptId);if($this->r()->withdrawResult($this->i(),$attemptId)){$cancelled=(new \App\Services\Sms\SmsAutomation($this->app->database()))->onlineResultWithdrawn($this->i(),$attemptId);Flash::add('success','Result withdrawn. The student and parent can no longer see it.'.($cancelled?' Its result SMS had not gone out yet and was cancelled.':''));}return Response::redirect(url('/admin/online-tests/'.($a['test_id']??'').'/submissions'));}
}
